import json
import sys

def main():
    try:
        input_data = sys.stdin.read()
        if not input_data.strip():
            return

        data = json.loads(input_data)

        if not isinstance(data, list):
            print(json.dumps({"error": "Input must be a JSON array"}), file=sys.stderr)
            sys.exit(1)

        numeric_values = []
        for item in data:
            if isinstance(item, (int, float)):
                numeric_values.append(item)
            elif isinstance(item, str):
                try:
                    numeric_values.append(float(item))
                except ValueError:
                    print(json.dumps({"error": f"Invalid numeric value: {item}"}), file=sys.stderr)
                    sys.exit(1)
            else:
                print(json.dumps({"error": f"Unsupported element type: {type(item).__name__}"}), file=sys.stderr)
                sys.exit(1)

        if len(numeric_values) == 0:
            print(json.dumps({"error": "No numeric values found in input"}), file=sys.stderr)
            sys.exit(1)

        mean_value = sum(numeric_values) / len(numeric_values)
        result = {"mean": mean_value}
        print(json.dumps(result))
    except json.JSONDecodeError as e:
        print(json.dumps({"error": f"Invalid JSON: {e}"}), file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(json.dumps({"error": str(e)}), file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
